(OutSystems.Model.IESpace eSpace) => {
    
    /*** creating IMobileTheme 'CarparkAvailability' ***/
    var carparkAvailability = eSpace.CreateMobileTheme("CarparkAvailability");
    carparkAvailability.AddOrUpdateThemeValues(new Dictionary<ThemeProperty, string> {
        {ThemeProperty.PrimaryColor, "#dc3023"},
        {ThemeProperty.CreatedWithoutCustomCSS, "true"},
        {ThemeProperty.SecondaryColor, "#dc3023"},
        {ThemeProperty.AppPrimaryColor, "#dc3023"},
    });
    var outSystemsUI = eSpace.References.Named("OutSystemsUI");
    var outSystemsUI2 = outSystemsUI.MobileThemes.Named("OutSystemsUI");
    carparkAvailability.BaseTheme = outSystemsUI2;
    carparkAvailability.Columns = 12; // default value
    carparkAvailability.ColumnWidth = 60; // default value
    carparkAvailability.Description = "Application theme";
    carparkAvailability.Folder = null; // default value
    carparkAvailability.Footer = null; // default value
    carparkAvailability.GridType = OutSystems.Model.Enumerations.GridType.Fluid;
    carparkAvailability.GutterWidth = 20; // default value
    carparkAvailability.GutterWidthPercentage = 30; // default value
    carparkAvailability.Header = null; // default value
    carparkAvailability.IconLibrary = null;
    var layouts = eSpace.MobileFlows.Named("Layouts");
    var layoutTopMenu = layouts.Nodes.OfType<OutSystems.Model.UI.Mobile.IMobileBlock>().Named("LayoutTopMenu");
    carparkAvailability.Layout = layoutTopMenu;
    carparkAvailability.MaxWidth = 1280;
    var common = eSpace.MobileFlows.Named("Common");
    var menu = common.Nodes.OfType<OutSystems.Model.UI.Mobile.IMobileBlock>().Named("Menu");
    carparkAvailability.Menu = menu;
    carparkAvailability.MinWidth = null; // default value
    carparkAvailability.Public = true;
    carparkAvailability.Shareable = true;
    carparkAvailability.StyleSheet = "/* ===================================================================== */\r\n/*  The following CSS was created using Theme Editor.                    */\r\n/*  To modify this CSS, click \"Open Theme Editor\".                       */\r\n/* ===================================================================== */\r\n\r\n/* ===================================================================== */\r\n/*  Root - CSS Variables                                                 */\r\n/* ===================================================================== */\r\n\r\n:root {\r\n\t\r\n    /* Color - Brand */\r\n    --color-primary: #dc3023;\r\n    --color-secondary: #dc3023;\r\n\r\n    --color-primary-hover: #a5241a;\r\n    --color-primary-selected: rgba(220, 48, 35, .12);\r\n\t\r\n    /* Dark Theme */\r\n    --background-dark-theme: rgba(255, 255, 255, .1);\r\n    --background-dark-theme-hover: rgba(255, 255, 255, .2);\r\n}\r\n\r\n\r\np-theme-start { }\n\n/* Singapore Carpark Availability dashboard. Status colours meet WCAG 2.2 AA (4.5:1) for text on their tint. */\n:root {\n    --cp-ink: #1b1f24;\n    --cp-ink-muted: #4a5561;\n    --cp-border: #d5dbe1;\n    --cp-surface: #ffffff;\n    --cp-surface-muted: #f4f6f8;\n    --cp-accent: #0b3a6e;\n    --cp-focus: #0b57d0;\n    --cp-radius: 8px;\n    --cp-high-ink: #0b6b33;      --cp-high-bg: #e6f4ea;      --cp-high-bar: #1a8a47;\n    --cp-moderate-ink: #7a4b00;  --cp-moderate-bg: #fff4dc;  --cp-moderate-bar: #c98a00;\n    --cp-low-ink: #9a3a00;       --cp-low-bg: #fdebdd;       --cp-low-bar: #e06c00;\n    --cp-full-ink: #a1141c;      --cp-full-bg: #fde8e9;      --cp-full-bar: #c8102e;\n    --cp-unknown-ink: #4a5561;   --cp-unknown-bg: #eef1f4;   --cp-unknown-bar: #8a96a3;\n}\n\n.cp-page-title { font-size: 28px; font-weight: 700; line-height: 1.2; color: var(--cp-ink); }\n.cp-header-actions { display: flex; align-items: center; gap: var(--space-s); }\n.cp-refresh-btn { min-height: 44px; min-width: 140px; }\n.cp-refresh-btn[aria-busy=\"true\"]::before {\n    content: \"\"; display: inline-block; width: 14px; height: 14px; margin-right: 8px; vertical-align: -2px;\n    border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%;\n    animation: cp-spin .8s linear infinite;\n}\n@keyframes cp-spin { to { transform: rotate(360deg); } }\n\n.cp-dashboard { display: flex; flex-direction: column; gap: var(--space-m); color: var(--cp-ink); }\n.cp-intro { display: flex; flex-direction: column; gap: var(--space-s); }\n.cp-subtitle { color: var(--cp-ink-muted); font-size: 16px; max-width: 72ch; }\n.cp-freshness-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-s) var(--space-base); }\n.cp-updated { color: var(--cp-ink-muted); font-size: 14px; }\n.cp-freshness-row .cp-refresh-btn { margin-left: auto; }\n@media (max-width: 640px) { .cp-freshness-row .cp-refresh-btn { margin-left: 0; } }\n\n.cp-fresh { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; border: 1px solid; font-size: 14px; font-weight: 600; }\n.cp-fresh::before { content: \"\"; width: 8px; height: 8px; border-radius: 50%; background: currentColor; }\n.cp-fresh-live { color: var(--cp-high-ink); background: var(--cp-high-bg); }\n.cp-fresh-stale, .cp-fresh-cached { color: var(--cp-moderate-ink); background: var(--cp-moderate-bg); }\n.cp-fresh-unavailable { color: var(--cp-full-ink); background: var(--cp-full-bg); }\n.cp-fresh-loading { color: var(--cp-unknown-ink); background: var(--cp-unknown-bg); }\n\n.cp-banners:empty { display: none; }\n.cp-banners .alert { margin-bottom: var(--space-s); }\n.cp-quality-note { font-size: 13px; color: var(--cp-ink-muted); }\n\n.cp-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--space-base); }\n.cp-kpis .card { height: 100%; margin: 0; border: 1px solid var(--cp-border); border-radius: var(--cp-radius); box-shadow: none; }\n.cp-kpi-label { font-size: 12px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--cp-ink-muted); }\n.cp-kpi-value { font-size: 30px; font-weight: 700; line-height: 1.2; margin: 4px 0; font-variant-numeric: tabular-nums; color: var(--cp-ink); }\n.cp-kpi-hint { font-size: 13px; color: var(--cp-ink-muted); }\n.cp-kpi-available .cp-kpi-value { color: var(--cp-high-ink); }\n.cp-kpi-full .cp-kpi-value { color: var(--cp-full-ink); }\n.cp-kpi-scope { font-size: 13px; color: var(--cp-ink-muted); margin-top: calc(var(--space-s) * -1); }\n\n.cp-filters { margin: 0; border: 1px solid var(--cp-border); border-radius: var(--cp-radius); box-shadow: none; }\n.cp-filter-grid { display: grid; grid-template-columns: minmax(220px, 2fr) repeat(4, minmax(150px, 1fr)) auto; gap: var(--space-base); align-items: end; }\n.cp-field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }\n.cp-field label { font-size: 14px; font-weight: 600; color: var(--cp-ink); margin: 0; }\n.cp-field input, .cp-field select, .cp-field .dropdown-container { width: 100%; min-height: 44px; }\n.cp-field-clear { justify-content: flex-end; }\n\n.cp-legend { display: flex; flex-wrap: wrap; gap: 4px var(--space-s); font-size: 13px; color: var(--cp-ink-muted); }\n.cp-legend-title { font-weight: 600; color: var(--cp-ink); }\n\n.cp-results-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: var(--space-s); }\n.cp-section-title { font-size: 20px; font-weight: 700; }\n.cp-results-count { font-size: 14px; color: var(--cp-ink-muted); }\n\n.cp-gallery .list-item, .cp-card-wrap { height: 100%; }\n.cp-gallery .list > script { display: none !important; }\n.cp-card { display: block; height: 100%; padding: var(--space-base); background: var(--cp-surface); color: var(--cp-ink);\n    border: 1px solid var(--cp-border); border-radius: var(--cp-radius); text-decoration: none; transition: box-shadow .15s ease, border-color .15s ease; }\n.cp-card:hover { border-color: var(--cp-accent); box-shadow: 0 2px 8px rgba(16, 24, 40, .12); text-decoration: none; color: var(--cp-ink); }\n.cp-card-inner { display: flex; flex-direction: column; gap: var(--space-s); height: 100%; }\n.cp-card-top { display: flex; justify-content: space-between; align-items: flex-start; gap: var(--space-s); }\n.cp-card-id { font-size: 18px; font-weight: 700; letter-spacing: .02em; }\n.cp-card-address { font-size: 14px; color: var(--cp-ink-muted); min-height: 2.6em; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n.cp-card-figure { display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px; }\n.cp-avail-number { font-size: 40px; font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; }\n.cp-avail-caption { font-size: 14px; color: var(--cp-ink-muted); }\n.cp-meter { height: 8px; background: #e3e8ed; border-radius: 4px; overflow: hidden; }\n.cp-meter-bar { height: 100%; border-radius: 4px; max-width: 100%; }\n.cp-card-pct { font-size: 14px; font-weight: 600; }\n.cp-card-foot { margin-top: auto; padding-top: var(--space-s); border-top: 1px solid var(--cp-border); display: flex; flex-wrap: wrap; gap: 6px var(--space-s); font-size: 12px; color: var(--cp-ink-muted); }\n\n.cp-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 600; white-space: nowrap; border: 1px solid transparent; }\n.cp-badge::before { font-weight: 700; }\n.cp-status-high.cp-badge { color: var(--cp-high-ink); background: var(--cp-high-bg); }\n.cp-status-high.cp-badge::before { content: \"\\2713\" / \"\"; }\n.cp-status-moderate.cp-badge { color: var(--cp-moderate-ink); background: var(--cp-moderate-bg); }\n.cp-status-moderate.cp-badge::before { content: \"\\25D0\" / \"\"; }\n.cp-status-low.cp-badge { color: var(--cp-low-ink); background: var(--cp-low-bg); }\n.cp-status-low.cp-badge::before { content: \"!\" / \"\"; }\n.cp-status-full.cp-badge { color: var(--cp-full-ink); background: var(--cp-full-bg); }\n.cp-status-full.cp-badge::before { content: \"\\2715\" / \"\"; }\n.cp-status-unknown.cp-badge { color: var(--cp-unknown-ink); background: var(--cp-unknown-bg); }\n.cp-status-unknown.cp-badge::before { content: \"?\" / \"\"; }\n.cp-meter-bar.cp-status-high { background: var(--cp-high-bar); }\n.cp-meter-bar.cp-status-moderate { background: var(--cp-moderate-bar); }\n.cp-meter-bar.cp-status-low { background: var(--cp-low-bar); }\n.cp-meter-bar.cp-status-full { background: var(--cp-full-bar); }\n.cp-meter-bar.cp-status-unknown { background: var(--cp-unknown-bar); }\n\n.cp-flag { display: inline-block; padding: 1px 6px; border-radius: 4px; background: var(--cp-unknown-bg); color: var(--cp-ink-muted); }\n.cp-flag-outdated { background: var(--cp-moderate-bg); color: var(--cp-moderate-ink); font-weight: 600; }\n\n.cp-btn-secondary { background: var(--cp-surface); color: var(--cp-accent); border: 1px solid var(--cp-accent); min-height: 44px; }\n.cp-btn-secondary:hover { background: #eaf1f9; color: var(--cp-accent); }\n.cp-more { display: flex; justify-content: center; margin-top: var(--space-m); }\n\n.cp-skeleton-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-base); }\n.cp-skeleton { height: 220px; border-radius: var(--cp-radius); background: linear-gradient(90deg, #eef1f4 25%, #f6f8fa 50%, #eef1f4 75%); background-size: 200% 100%; animation: cp-shimmer 1.4s ease-in-out infinite; }\n@keyframes cp-shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }\n.cp-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }\n.cp-empty-title { font-size: 18px; font-weight: 700; color: var(--cp-ink); }\n.cp-empty-text { color: var(--cp-ink-muted); margin-top: 4px; }\n.cp-source { font-size: 12px; color: var(--cp-ink-muted); border-top: 1px solid var(--cp-border); padding-top: var(--space-base); }\n\n.cp-detail { width: min(640px, calc(100vw - 32px)); max-height: 85vh; overflow-y: auto; padding: 0; border-radius: var(--cp-radius); }\n.cp-detail-body { padding: var(--space-m); display: flex; flex-direction: column; gap: var(--space-base); }\n.cp-detail-head { display: flex; justify-content: space-between; align-items: center; gap: var(--space-base); }\n.cp-detail-title { font-size: 22px; font-weight: 700; }\n.cp-detail-address { color: var(--cp-ink-muted); }\n.cp-detail-section { display: flex; flex-direction: column; gap: var(--space-s); padding-top: var(--space-base); border-top: 1px solid var(--cp-border); }\n.cp-detail-subtitle { font-size: 16px; font-weight: 700; }\n.cp-lot-row { display: grid; grid-template-columns: minmax(120px, 1fr) auto auto; gap: var(--space-s) var(--space-base); align-items: center; padding: 6px 0; }\n.cp-lot-figure { font-variant-numeric: tabular-nums; }\n.cp-kv { display: grid; grid-template-columns: 180px 1fr; gap: var(--space-base); font-size: 14px; }\n.cp-k { color: var(--cp-ink-muted); }\n.cp-detail-note, .cp-detail-meta { font-size: 13px; color: var(--cp-ink-muted); }\n\n.cp-dashboard :focus-visible, .cp-header-actions :focus-visible, .cp-detail :focus-visible { outline: 3px solid var(--cp-focus); outline-offset: 2px; }\n.cp-card:focus-visible { border-color: var(--cp-focus); }\n\n@media (max-width: 1199px) {\n    .cp-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n    .cp-filter-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n    .cp-field-search { grid-column: 1 / -1; }\n    .cp-skeleton-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n}\n@media (max-width: 640px) {\n    .cp-page-title { font-size: 22px; }\n    .cp-header-actions, .cp-refresh-btn { width: 100%; }\n    .cp-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-s); }\n    .cp-kpi-value { font-size: 24px; }\n    .cp-filter-grid { grid-template-columns: 1fr; }\n    .cp-field-clear { justify-content: stretch; }\n    .cp-skeleton-grid { grid-template-columns: 1fr; }\n    .cp-avail-number { font-size: 34px; }\n    .cp-kv { grid-template-columns: 1fr; gap: 0; }\n    .cp-lot-row { grid-template-columns: 1fr auto; }\n    .cp-lot-figure { grid-column: 1 / -1; grid-row: 2; }\n}\n@media (prefers-reduced-motion: reduce) {\n    .cp-skeleton, .cp-refresh-btn[aria-busy=\"true\"]::before { animation: none; }\n    .cp-card { transition: none; }\n}\n@media (forced-colors: active) {\n    .cp-badge, .cp-fresh, .cp-card { border: 1px solid CanvasText; }\n    .cp-meter-bar { background: Highlight; }\n}\r\n";
}
